PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT ?child ?spouse WHERE {
  dbr:Spurius_Lucretius_Tricipitinus dbo:child ?child .
  {
    ?child dbo:spouse ?spouse .
  } UNION {
    ?child dbp:spouse ?spouse .
  } UNION {
    ?child dbp:husband ?spouse .
  } UNION {
    ?child dbp:spouses ?spouse .
  }
}

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?abs WHERE {
  dbr:Lucius_Tarquinius_Collatinus dbo:abstract ?abs .
  FILTER(langMatches(lang(?abs), "EN") && regex(str(?abs), "Lucretia", "i"))
} LIMIT 50

